package rv.batch.format;import java.util.Locale;public class DecimalFormatSymbols {private String[] digits;public static DecimalFormatSymbols getInstance(Locale l){DecimalFormatSymbols s=new DecimalFormatSymbols();char zero=java.text.DecimalFormatSymbols.getInstance(l).getZeroDigit();s.digits=new String[10];for(int i=0;i<10;i++)s.digits[i]=String.valueOf((char)(zero+i));return s;}public String[] getDigitStrings(){return digits.clone();}public void setDigitStrings(String[] s){if(s.length!=10)throw new IllegalArgumentException();digits=s.clone();}}